using System;using System.IO;using System.Linq;using System.Drawing;using System.Reflection;using System.Windows.Forms;using System.Collections.Generic;using V15Voice;
public static class TwoVoiceUiTests {
 static int count;static object F(object f,string n){return f.GetType().GetField(n,BindingFlags.Instance|BindingFlags.NonPublic).GetValue(f);}static object C(object f,string n,params object[] args){return f.GetType().GetMethod(n,BindingFlags.Instance|BindingFlags.NonPublic).Invoke(f,args);}static void Check(bool b,string n){if(!b)throw new Exception(n);count++;Console.WriteLine("PASS "+n);}static Rectangle Screen(Control c){return c.RectangleToScreen(c.ClientRectangle);}static bool Visible(Control c){return c.Visible&&Screen(c).Height>=24&&Screen(c).Width>=80&&Screen(c.Parent).Contains(Screen(c));}
 [STAThread]public static int Main(){Application.EnableVisualStyles();var f=new MainForm();try{f.Show();Application.DoEvents();var mode=(ComboBox)F(f,"voiceMode");var second=(ComboBox)F(f,"secondVoice");var grid=(DataGridView)F(f,"grid");var catalog=(VoiceCatalog)F(f,"catalog");catalog.Add(new VoiceProfile{Key="K:16",Name="Michael",Kind=EngineKind.Kokoro,Speaker=16,Styles="Kể chuyện",Gender="Nam",Description="Test only"});catalog.Add(new VoiceProfile{Key="U:clone",Name="VANZAI riêng",Kind=EngineKind.Chatterbox,ReferencePath="private.wav",Styles="Review"});C(f,"FillSecondVoice","");Check(mode.SelectedIndex==0&&!grid.Columns["speaker"].Visible&&!second.Enabled,"Default single-voice mode keeps old workflow");Check(second.Items.Cast<VoiceItem>().Any(v=>v.Key=="U:clone")&&second.Items.Cast<VoiceItem>().Any(v=>v.Key=="C:adam_rvc"),"B chooser includes private clones and community voices");
  string source=Path.Combine(Path.GetTempPath(),"twoVoice-ui-"+Guid.NewGuid().ToString("N")+".srt");File.WriteAllText(source,"1\n00:00:00,000 --> 00:00:02,000\n[A] First line.\n\n2\n00:00:02,000 --> 00:00:04,000\n[B] Second line.\n\n3\n00:00:04,000 --> 00:00:06,000\n[B] Third line.\n");C(f,"LoadFile",source);Check(mode.SelectedIndex==1&&grid.Columns["speaker"].Visible&&(string)grid.Rows[1].Cells["speaker"].Value=="B","Opening labelled SRT auto-enables dual voice and populates speaker column");Check((string)grid.Rows[0].Cells[3].Value=="First line.","Grid editor shows clean spoken text without label");C(f,"FillSecondVoice","K:16");var saved=(VoiceSettings)C(f,"CaptureSettings");Check(saved.TwoVoices&&saved.VoiceBKey=="K:16","Studio and queue share explicit A/B mapping");
  using(var b=(KokoroEngine)C(f,"CueEngine",((List<Cue>)F(f,"cues"))[1]))Check(b.VoiceName=="Michael"&&b.Speaker==16,"Preview B uses B engine rather than current A selection");
  ((ComboBox)F(f,"breathMode")).SelectedIndex=2;var options=(RenderOptions)C(f,"OptionsForRun",false);Check(options.TwoVoices&&options.VoiceBKey=="K:16"&&options.VoiceAInfo.Length>0,"Export options carry both voice profiles and shared settings");using(var routed=(KokoroEngine)C(f,"RunEngine",(List<Cue>)F(f,"cues"))){routed.SelectSpeaker("B");Check(routed is TwoVoiceEngine&&routed.VoiceName=="Michael","Export factory creates a router with selected B profile");}
  C(f,"AssignSpeakers","alternate");Check(grid.Rows.Cast<DataGridViewRow>().Select(r=>(string)r.Cells["speaker"].Value).SequenceEqual(new[]{"A","B","A"}),"One-click alternating assignment is optional and editable");grid.ClearSelection();grid.Rows[0].Selected=true;grid.Rows[2].Selected=true;C(f,"AssignSpeakers","B");Check(((List<Cue>)F(f,"cues")).All(c=>c.Speaker=="B"),"Bulk assignment applies to selected rows without forcing alternation");
  mode.SelectedIndex=0;var current=(List<Cue>)F(f,"cues");C(f,"ReadGrid");Check(current.All(c=>c.Speaker=="B"),"Changing mode does not erase existing role labels");mode.SelectedIndex=1;
  foreach(var size in new[]{new Size(1440,960),new Size(1280,850),new Size(1100,740)}){f.Size=size;f.Location=Point.Empty;Application.DoEvents();Check(Visible(mode)&&Visible(second),"Two-voice selectors remain reachable at "+size);Check(Visible((Control)F(f,"voices"))&&Visible((Control)F(f,"preview")),"A picker and preview remain reachable at "+size);Check(((TabControl)F(f,"studioSettings")).SelectedTab.ClientSize.Height>=100,"Settings remain usable at "+size);using(var bm=new Bitmap(f.Width,f.Height)){using(var g=Graphics.FromImage(bm))g.CopyFromScreen(f.Location,Point.Empty,f.Size);bm.Save(Path.Combine(AppDomain.CurrentDomain.BaseDirectory,"validation/two-voice-"+size.Width+".png"));}}
  C(f,"SetBusy",true);Check(!mode.Enabled&&!second.Enabled&&((Control)F(f,"cancel")).Enabled,"Busy render locks both voice mappings while Stop remains available");C(f,"SetBusy",false);Check(mode.Enabled&&second.Enabled,"Both selectors unlock after completion");
  C(f,"Apply",VoiceSettings.From(saved.Xml()));Check(mode.SelectedIndex==1&&(string)C(f,"SecondKey")=="K:16","Restoring session/preset restores two-voice mapping");C(f,"AddFiles",(object)new string[]{source});var jobs=(List<BatchJob>)F(f,"jobs");Check(jobs.Last().Cues[1].Speaker=="B"&&((Label)F(f,"batchInfo")).Text.Contains("B: Michael"),"Queue import preserves labels and displays shared mapping");
  var j=jobs.Last();C(f,"EditQueued");grid.Rows[0].Cells["speaker"].Value="B";C(f,"ReadGrid");Check(j.Cues[0].Speaker=="B"&&j.State==JobState.Queued,"Queued-file editor propagates manual voice changes to render input");var state=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"V15VoiceStudio");C(f,"SaveSession");Check(QueueStore.Load(Path.Combine(state,"queue.xml")).Last().Cues[0].Speaker=="B","Manual role changes survive queue persistence");
  string txt=Path.ChangeExtension(source,".txt");File.WriteAllText(txt,"[A] First sentence. Another sentence.\n[B] Final sentence.");C(f,"LoadFile",txt);C(f,"SaveProseProject");Check(C(f,"RestoreProseProject").Equals(true)&&((List<Cue>)F(f,"cues")).Last().Speaker=="B","TXT project restore keeps roles after sentence splitting");
  Check(((TabControl)F(f,"tabs")).TabCount==7,"Existing seven tabs retained; removed video editor stays removed");Console.WriteLine("TOTAL TWO VOICE UI "+count+" passed.");return 0;
 }catch(Exception e){Console.WriteLine(e);return 1;}finally{f.Close();}}
}
